insert into learning_evidences (id, dba_id, num, texto) select 'bcf49e70-0102-432b-81aa-9622b078b093'::uuid, d.id, 1, 'Identifica en fichas u objetos reales los valores de la variable en estudio.' from dbas d join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1 and d.num = 10;
